// single-item input: the config node emits exactly one row.
const cfg = $('Set Repricing Rules').first().json;
const maxProducts = Number(cfg.max_products) || 20;

const products = $('Read Store Products').all().map((i) => i.json);
const mapRows = $('Read Competitor Map').all().map((i) => i.json);

// The sheet is keyed by SKU. Anything without one cannot be matched to a
// product, and anything without a competitor URL has nothing to compare to.
const bySku = new Map();
for (const r of mapRows) {
  const sku = String(r.sku || '').trim();
  const url = String(r.amazon_url || '').trim();
  if (sku && /^https?:\/\//i.test(url)) bySku.set(sku, r);
}

const pairs = [];
const unmapped = [];
for (const p of products) {
  const sku = String(p.sku || '').trim();
  const row = sku ? bySku.get(sku) : null;
  if (!row) { unmapped.push(p.name || sku || String(p.id)); continue; }

  // Woo sends prices as strings, and an empty string is not zero - it means the
  // product has no sale price set, which is a different thing from a sale price
  // of nothing.
  const regular = Number(p.regular_price);
  const current = Number(p.price);
  if (!isFinite(current) || current <= 0) { unmapped.push(p.name || sku); continue; }

  pairs.push({
    product_id: p.id,
    sku,
    store_title: p.name,
    current_price: current,
    regular_price: isFinite(regular) && regular > 0 ? regular : current,
    sale_price: p.sale_price === '' ? null : Number(p.sale_price),
    cost: Number(row.cost) || 0,
    amazon_url: String(row.amazon_url).trim(),
  });
  if (pairs.length >= maxProducts) break;
}

// A filtering node that can return zero items ends the branch, and then the
// "nothing to do" path below never runs either. Emit a marker instead.
if (!pairs.length) {
  return [{ json: { nothing_to_check: true, product_count: products.length,
                    mapped_count: 0, unmapped } }];
}

return [{ json: {
  payload: pairs.map((p) => ({ url: p.amazon_url })),
  pairs,
  checked_count: pairs.length,
  product_count: products.length,
  unmapped,
  scanned_at: new Date().toISOString(),
} }];

// single-item input: the trigger endpoint answers once for the whole batch.
const res = $input.first().json;

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, so the status code proves nothing on its own.
if (res && res.error) {
  throw new Error('Bright Data refused the scrape: ' + JSON.stringify(res.error));
}
if (!res || !res.snapshot_id) {
  throw new Error('No snapshot_id came back: ' + JSON.stringify(res).slice(0, 300));
}
return [{ json: { snapshot_id: res.snapshot_id } }];

// single-item input: the progress endpoint answers once per poll.
const res = $input.first().json;
const status = String((res && res.status) || '').toLowerCase();

// $runIndex is the poll count. Without a cap a stuck snapshot spins all night.
const polls = $runIndex + 1;
const MAX_POLLS = 20;

if (status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 300));
}
if (polls >= MAX_POLLS && status !== 'ready') {
  throw new Error('Snapshot still ' + (status || 'unknown') + ' after ' + polls + ' polls. Raise MAX_POLLS or cut max_products.');
}

return [{ json: { ready: status === 'ready', status, polls,
                  snapshot_id: $('Check Scrape Accepted').first().json.snapshot_id } }];

const rows = $input.all().map((i) => i.json).filter((r) => r && !r.error);
const src = $('Build Price Check List').first().json;
const pairs = src.pairs || [];

// Rows come back keyed by the URL that was sent, which is the only reliable way
// to join them - titles differ on both sides, that being the whole problem.
const byUrl = new Map();
for (const r of rows) {
  const u = (r.input && r.input.url) || r.url || '';
  if (u) byUrl.set(String(u).trim(), r);
}

const out = [];
const missing = [];
for (const p of pairs) {
  const r = byUrl.get(p.amazon_url);
  // Two runs of this dataset returned 1 of 2 rows and then 3 of 4. A product
  // Bright Data did not return is not a product with no competition, so it is
  // named in the digest rather than dropped.
  if (!r) { missing.push(p.sku); continue; }

  const available = r.is_available === true ||
    /in stock/i.test(String(r.availability || ''));

  out.push({ json: {
    ...p,
    amazon_title: r.title_clean || r.title || '',
    // Buy-box price only. other_sellers_prices carried an Amazon Resale unit at
    // $84.15 next to a $99 new price, and repricing a new product against a
    // used one is how a shop ends up underwater.
    amazon_price: Number(r.final_price),
    amazon_list_price: Number(r.initial_price) || null,
    amazon_currency: r.currency || 'USD',
    amazon_available: available,
    buybox_seller: r.buybox_seller || r.seller_name || '',
  } });
}

if (!out.length) {
  return [{ json: { nothing_to_check: true, missing,
                    checked_count: src.checked_count || 0 } }];
}
// Stash the misses on the first item so the report can name them.
out[0].json.missing_skus = missing;
return out;

