const cfg = $('Set Repricing Rules').first().json;
const undercut = Number(cfg.undercut_percent) || 0;
const minMargin = Number(cfg.min_margin_percent) || 0;
const maxChange = Number(cfg.max_change_percent) || 10;
const dryRun = String(cfg.dry_run) !== 'false';

const round2 = (n) => Math.round(n * 100) / 100;

const changes = [];
const held = [];
let considered = 0;

// The Information Extractor does not merge its answer into the item, it
// REPLACES it - every row arrives as `{output: {...}}` and nothing else. So the
// product cannot be looked up by sku here, because there is no sku to look up
// with. The extractor emits one item per input item in the same order, so the
// join is positional. Matching on a field that no longer exists silently found
// nothing and made every product look out of stock, on a fully green run.
const prep = $('Prepare Match Check').all().map((x) => x.json);
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const src = prep[i] || {};
  if (j.nothing_to_check || src.nothing_to_check || !src.sku) continue;

  const verdict = (j.output && typeof j.output === 'object') ? j.output : j;
  const same = String(verdict.same_product || '').toLowerCase();
  const confidence = String(verdict.confidence || '').toLowerCase();

  considered++;
  const row = {
    sku: src.sku, product_id: src.product_id, store_title: src.store_title,
    amazon_title: src.amazon_title, current_price: src.current_price,
    amazon_price: src.amazon_price, cost: src.cost,
  };

  if (same !== 'yes' || confidence === 'low') {
    held.push({ ...row, reason: 'not the same product' }); continue;
  }
  if (!src.amazon_available) {
    held.push({ ...row, reason: 'out of stock on Amazon' }); continue;
  }
  const comp = Number(src.amazon_price);
  if (!isFinite(comp) || comp <= 0) {
    held.push({ ...row, reason: 'no usable competitor price' }); continue;
  }

  // A price far away from the shop's own is far more likely to be the wrong
  // product than a real opportunity - a wrong ASIN in the sheet looks exactly
  // like a bargain otherwise.
  const ratio = comp / src.current_price;
  if (ratio < 0.4 || ratio > 2.5) {
    held.push({ ...row, reason: 'competitor price ' + ratio.toFixed(2) + 'x ours, treated as a bad match' });
    continue;
  }

  let target = round2(comp * (1 - undercut / 100));

  // Cost floor. A shop with no cost in the sheet gets no floor, so the margin
  // rule is skipped rather than applied against a cost of zero.
  const floor = src.cost > 0 ? round2(src.cost * (1 + minMargin / 100)) : null;
  if (floor !== null && target < floor) {
    held.push({ ...row, reason: 'target ' + target + ' below the ' + floor + ' margin floor' });
    continue;
  }

  // Never above the product's own regular price - a "sale" price higher than
  // the list price is not a sale, it is a bug the customer sees.
  if (target >= src.regular_price) {
    held.push({ ...row, reason: 'target ' + target + ' not below the regular price' });
    continue;
  }

  // One run should never move a price further than the shop owner expects.
  const cap = round2(src.current_price * (maxChange / 100));
  const delta = target - src.current_price;
  if (Math.abs(delta) > cap) {
    target = round2(src.current_price + Math.sign(delta) * cap);
  }

  if (Math.abs(target - src.current_price) < 0.01) {
    held.push({ ...row, reason: 'already at the right price' }); continue;
  }

  changes.push({
    ...row, new_price: target,
    change: round2(target - src.current_price),
    change_percent: round2(((target - src.current_price) / src.current_price) * 100),
    capped: Math.abs(delta) > cap,
  });
}

if (!changes.length) {
  return [{ json: { no_changes: true, considered, held, dry_run: dryRun } }];
}
return changes.map((c) => ({ json: { ...c, dry_run: dryRun, considered, held_count: held.length, held } }));

const cfg = $('Set Repricing Rules').first().json;
const src = $('Build Price Check List').first().json;
const prep = $('Prepare Match Check').first().json;

// Deliberately not reading $input here. On a live run this node is fed by the
// WooCommerce update, whose output is the shop's API response rather than the
// pricing decisions, so the decisions are read from the node that made them.
const changes = $('Decide New Prices').all().map((i) => i.json).filter((c) => !c.no_changes);
const held = (changes[0] && changes[0].held) || [];
const dryRun = String(cfg.dry_run) !== 'false';
const money = (n) => (Number(n) || 0).toFixed(2);
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');

const lines = [];
lines.push(dryRun
  ? '*Repricing preview* - dry_run is on, so nothing was changed in the shop.'
  : '*Repricing run* - sale prices updated in WooCommerce.');
lines.push('');

const missing = prep.missing_skus || [];
lines.push(
  plural(src.checked_count || 0, 'product') + ' checked against Amazon' +
  (missing.length ? ', ' + missing.length + ' with no data returned (' + missing.slice(0, 5).join(', ') + ')' : '') + '.'
);
lines.push(plural(changes.length, 'price') + ' to change, ' + plural(held.length, 'product') + ' held back.');
lines.push('');

for (const c of changes.slice(0, 15)) {
  lines.push(
    '• *' + c.store_title + '* (' + c.sku + ')  ' +
    money(c.current_price) + ' -> ' + money(c.new_price) +
    '  (' + (c.change_percent > 0 ? '+' : '') + c.change_percent + '%)' +
    '  Amazon ' + money(c.amazon_price) +
    (c.capped ? '  _capped by max_change_percent_' : '')
  );
}

// The held-back list is the part a shop owner actually needs to read, because
// it is where a wrong SKU in the sheet shows up.
if (held.length) {
  lines.push('');
  lines.push('*Held back*');
  for (const h of held.slice(0, 10)) {
    lines.push('• ' + h.sku + ' - ' + h.reason);
  }
}

const rows = changes.map((c) => ({
  checked_at: new Date().toISOString(),
  sku: c.sku, product: c.store_title, amazon_title: c.amazon_title,
  old_price: c.current_price, new_price: c.new_price,
  change_percent: c.change_percent, amazon_price: c.amazon_price,
  applied: dryRun ? 'preview' : 'applied',
}));

return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];

// Optional. Splice between 'Decide New Prices' and 'Any Price Changes?' when
// some products are already discounted by a campaign and must not be touched.
// A SKU listed here is reported as held rather than repriced.
const protectedSkus = ['SKU-LAUNCH-01', 'SKU-BUNDLE-02'];
const out = [];
for (const item of items) {
  const j = item.json || {};
  if (protectedSkus.includes(String(j.sku || ''))) {
    out.push({ json: { ...j, change: 0, new_price: j.current_price, held_reason: 'on promotion' } });
  } else {
    out.push({ json: j });
  }
}
return out;
